                // TODO(DESK-296): Order correctly
                .orderBy(tMessage.ordinal, 'asc')
                .limit(1)
                .executeSelectNoneOrOne(),
        );
        if (uid === null) {
            return undefined;
        }

        return this.getMessageByUid(uid);
    }

