    private _getMessagesByOrdinal(
        conversationUid: DbConversationUid,
        ordinal: u53,
        direction: MessageQueryDirection,
        limit?: u53,
    ): DbList<DbAnyMessage, 'uid'> {
        // Determine ordering and dynamic WHERE clause: Filter by conversation
        // and by ordinal.
        //
        // Note: The plain range condition on the `ordinal` column (instead of e.g. an OR-condition
        //       over `processedAt` and `createdAt`) is required so that the query can be served by
        //       the index on `(conversationUid, ordinal)`.
        let ordinalCondition;
        let orderByMode: 'asc' | 'desc';
        switch (direction) {
            case MessageQueryDirection.OLDER:
                orderByMode = 'desc';
                ordinalCondition = tMessage.ordinal.lessOrEquals(ordinal);
                break;

            case MessageQueryDirection.NEWER:
                orderByMode = 'asc';
                ordinalCondition = tMessage.ordinal.greaterOrEquals(ordinal);
                break;

            default:
                unreachable(direction);
        }

        return sync(
            this._db
                .selectFrom(tMessage)
                .select({
                    uid: tMessage.uid,
                    ordinal: tMessage.ordinal,
                })
                .where(tMessage.conversationUid.equals(conversationUid).and(ordinalCondition))
                // TODO(DESK-296): Order correctly
                .orderBy('ordinal', orderByMode)
                .limitIfValue(limit)
                .executeSelectMany(),
        );
    }

    private _getStatusMessagesByOrdinal(
        conversationUid: DbConversationUid,
        ordinal: u53,
        direction: MessageQueryDirection,
        limit?: u53,
    ): DbList<DbAnyStatusMessage, 'uid'> {
        // Determine ordering and dynamic WHERE clause: Filter by conversation
        // and by processedAt timestamp.
        let createdAtCondition;
        let orderByMode: 'asc' | 'desc';
        switch (direction) {
            case MessageQueryDirection.OLDER:
                orderByMode = 'desc';
                createdAtCondition = tStatusMessage.createdAtTimestamp.lessOrEquals(ordinal);
                break;
            case MessageQueryDirection.NEWER:
                orderByMode = 'asc';
                createdAtCondition = tStatusMessage.createdAtTimestamp.greaterOrEquals(ordinal);

                break;
            default:
                unreachable(direction);
        }

        return sync(
            this._db
                .selectFrom(tStatusMessage)
                .select({
                    uid: tStatusMessage.uid,
                    ordinal: tStatusMessage.createdAtTimestamp,
                })
                .where(
                    tStatusMessage.conversationUid.equals(conversationUid).and(createdAtCondition),
                )
                .orderBy('ordinal', orderByMode)
                .limitIfValue(limit)
                .executeSelectMany(),
        );
    }

    /** @inheritdoc */
    public getMessageUids(
        conversationUid: DbConversationUid,
        limit?: u53,
        reference?: {
            readonly ordinal: u53;
            readonly direction: MessageQueryDirection;
        },
    ): DbList<DbAnyMessage, 'uid'> {
        // Fields to select
        const selectFields = {
            uid: tMessage.uid,
            ordinal: tMessage.ordinal,
        };

        // If the reference UID is undefined, we start at the newest message.
        if (reference === undefined) {
            return sync(
                this._db
                    .selectFrom(tMessage)
                    .select(selectFields)
                    .where(tMessage.conversationUid.equals(conversationUid))
                    // TODO(DESK-296): Order correctly
                    .orderBy('ordinal', 'desc')
                    .limitIfValue(limit)
                    .executeSelectMany(),
            );
        }

        return this._getMessagesByOrdinal(
            conversationUid,
            reference.ordinal,
            reference.direction,
            limit,
        );
    }

    /** @inheritdoc */
    public getStatusMessageUids(
        conversationUid: DbConversationUid,
        limit?: u53,
        reference?: {
            readonly ordinal: u53;
            readonly direction: MessageQueryDirection;
        },
    ): DbList<DbAnyStatusMessage, 'uid'> {
        // Fields to select
        const selectFields = {
            uid: tStatusMessage.uid,
            ordinal: tStatusMessage.createdAtTimestamp,
