                    .where(tStatusMessage.conversationUid.equals(conversationUid))
                    .orderBy('ordinal', 'desc')
                    .limitIfValue(limit)
                    .executeSelectMany(),
            );
        }

        return this._getStatusMessagesByOrdinal(
            conversationUid,
            reference.ordinal,
            reference.direction,
            limit,
        );
    }

