    /** @inheritdoc */
    public setSettings<TKey extends keyof Settings>(
        category: TKey,
        settings: Settings[TKey],
    ): Settings[TKey] {
        const settingsBytes: Uint8Array = SETTINGS_CODEC[category].encode(settings);

        sync(
            this._db
                .insertInto(tSettings)
                .set({category, settingsBytes})
                .onConflictOn(tSettings.category)
                .doUpdateSet({settingsBytes})
                .executeInsert(),
        );

        return settings;
    }

    /** @inheritdoc */
    public getSettings<TKey extends keyof Settings>(category: TKey): Settings[TKey] | undefined {
        const settingsBytes = sync(
            this._db
                .selectFrom(tSettings)
                .where(tSettings.category.equals(category))
                .selectOneColumn(tSettings.settingsBytes)
                .executeSelectNoneOrOne(),
        );

        if (settingsBytes === null) {
            return undefined;
        }

        return SETTINGS_CODEC[category].decode(settingsBytes);
    }

    /** @inheritdoc */
    public getPreferredEmojiSkinTones(): DbList<
        DbEmojiSkinTone,
        'baseEmoji' | 'preferredSkinToneEmoji'
    > {
        return sync(
            this._db
                .selectFrom(tEmojiSkinTones)
                .select({
                    baseEmoji: tEmojiSkinTones.baseEmoji,
                    preferredSkinToneEmoji: tEmojiSkinTones.preferredSkinToneEmoji,
                })
                .executeSelectMany(),
            // We filter out any values that are not known to the current emoji implementation so that
            // the type system does not deceive us.
        ).filter((row) => {
            if (!isSingleUnicodeEmoji(row.baseEmoji)) {
                this._log.error(
                    `Unknown baseEmoji value "${row.baseEmoji}" in emoji skin tone table`,
                );
                return false;
            }
            if (!isSingleUnicodeEmoji(row.preferredSkinToneEmoji)) {
                this._log.error(
                    `Unknown preferredSkinToneEmoji value ${row.preferredSkinToneEmoji} in emoji skin tone table`,
                );
                return false;
            }
            return true;
        });
    }

    /** @inheritdoc */
    public setPreferredSkinToneEmoji(
        baseEmoji: SingleUnicodeEmoji,
        preferredSkinToneEmoji: SingleUnicodeEmoji,
    ): void {
        sync(
            this._db
                .insertInto(tEmojiSkinTones)
                .set({
                    baseEmoji,
                    preferredSkinToneEmoji,
                })
                .onConflictDoUpdateSet({baseEmoji, preferredSkinToneEmoji})
                .where(tEmojiSkinTones.baseEmoji.equals(baseEmoji))
                .executeInsert(),
        );
    }

    /** @inheritdoc */
    public getSortedFavoriteEmojis(mode: FavoriteEmojisSortMode, limit?: u53): FavoriteEmojis {
        const orderBy = mode === 'most-recent' ? 'lastUsedAt desc' : 'nUsed desc, lastUsedAt desc';

        return sync(
            this._db
                .selectFrom(tEmojiData)
                .select({
                    emoji: tEmojiData.emoji,
                    lastUsedAt: tEmojiData.lastUsedAt,
                    nUsed: tEmojiData.nUsed,
                })
                .orderByFromString(orderBy)
                .limitIfValue(limit)
                .executeSelectMany(),
        );
    }

    /** @inheritdoc */
    public addOrIncreaseEmojiUsageCount(emoji: SingleUnicodeEmoji): void {
        // We need to fetch the value here since we cannot inline update a database value based on
        // its former value.
        const nUsed = sync(
            this._db
                .selectFrom(tEmojiData)
                .selectOneColumn(tEmojiData.nUsed)
                .where(tEmojiData.emoji.equals(emoji))
                .executeSelectNoneOrOne(),
        );
        // Insert
        if (nUsed === null) {
            sync(
                this._db
                    .insertInto(tEmojiData)
                    .set({
                        emoji,
                        lastUsedAt: new Date(),
                        nUsed: 1,
                    })
                    .onConflictDoNothing()
                    .executeInsert(),
            );
            return;
        }
        // Update
        sync(
            this._db
                .update(tEmojiData)
                .set({
                    emoji,
                    lastUsedAt: new Date(),
