                //         .executeSelectMany(),
                // );

                const poll =
                    sync(
                        this._db
                            .selectFrom(tMessagePollData)
                            .innerJoin(tPolls)
                            .on(tPolls.uid.equals(tMessagePollData.pollUid))
                            .select({
                                uid: tPolls.uid,
                                pollId: tPolls.pollId,
