    private _getReceiverLookup({
        contactReceiverLookup,
        groupReceiverLookup,
    }: {
        readonly contactReceiverLookup?: DbContactUid;
        readonly groupReceiverLookup?: DbGroupUid;
    }): DbReceiverLookup {
        let receiverLookup: DbReceiverLookup | undefined = undefined;
        if (contactReceiverLookup !== undefined) {
            receiverLookup = {
                type: ReceiverType.CONTACT,
                uid: contactReceiverLookup,
            };
        } else if (groupReceiverLookup !== undefined) {
            receiverLookup = {
                type: ReceiverType.GROUP,
                uid: groupReceiverLookup,
            };
        }
        // TODO(DESK-236): Implement distribution list.
        assert(receiverLookup !== undefined, 'Unexpected message without any associated receiver');

        return receiverLookup;
    }

    /** @inheritdoc */
    public getMessagesByContactIdentities(
        contactIdentities: IdentityString[],
        chunkParameters?: {
            limit: u53;
            offset: u53;
        },
    ): {
        readonly message: DbGet<DbAnyMessage>;
        readonly receiverLookup: DbReceiverLookup;
    }[] {
        const contactUids = sync(
            this._db
                .selectFrom(tContact)
                .selectOneColumn(tContact.uid)
                .where(tContact.identity.in(contactIdentities))
                .executeSelectMany(),
        );
        const results = sync(
            this._getCommonMessageSelectorWithConversation()
                .where(
                    tMessage.senderContactUid
                        .in(contactUids)
                        .or(tMessage.senderContactUid.isNull()),
                )
                .limitIfValue(chunkParameters?.limit)
                .offsetIfValue(chunkParameters?.offset)
                .executeSelectMany(),
        );

        return results.map((messageCommon) => ({
            message: this._getMessage(messageCommon),
            receiverLookup: this._getReceiverLookup(messageCommon),
        }));
    }

    /** @inheritdoc*/
    public getMessages(chunkParameters?: {limit: u53; offset: u53}): (Pick<
        DbAnyMessage,
        'id' | 'deletedAt' | 'createdAt' | 'senderContactUid' | 'conversationUid' | 'type'
    > & {
        lastEditedAt?: Date;
        text: string | undefined;
    })[] {
        const messages = sync(
            this._getCommonMessageSelector()
                .limitIfValue(chunkParameters?.limit)
                .offsetIfValue(chunkParameters?.offset)
                .executeSelectMany(),
        );

        return messages.map((message) => {
            const text = this.getMessageText(message);
            return {...message, text};
        });
    }

    /** @inheritdoc */
    public getStatusMessages(chunkParameters?: {limit: u53; offset: u53}): {
        message: DbAnyStatusMessage;
        receiverLookup: DbReceiverLookup;
    }[] {
        const results = sync(
            this._db
                .selectFrom(tStatusMessage)
                .innerJoin(tConversation)
                .on(tStatusMessage.conversationUid.equals(tConversation.uid))
                .select({
                    type: tStatusMessage.type,
                    conversationUid: tStatusMessage.conversationUid,
                    createdAt: tStatusMessage.createdAt,
                    createdAtTimestamp: tStatusMessage.createdAtTimestamp,
                    statusBytes: tStatusMessage.statusBytes,
                    uid: tStatusMessage.uid,
                    ordinal: tStatusMessage.createdAtTimestamp,
                    groupReceiverLookup: tConversation.groupUid,
                    contactReceiverLookup: tConversation.contactUid,
                })
                .limitIfValue(chunkParameters?.limit)
                .offsetIfValue(chunkParameters?.offset)
                .executeSelectMany(),
        );

        return results.map((statusMessageCommon) => ({
            message: {
                ...statusMessageCommon,
                id: statusMessageUidToStatusMessageId(statusMessageCommon.uid),
            },
            receiverLookup: this._getReceiverLookup(statusMessageCommon),
        }));
    }

    /** @inheritdoc */
    public getMessageText(message: Pick<DbAnyMessage, 'type' | 'uid'>): string | undefined {
        let text;
        switch (message.type) {
            case 'text':
                text = this._getMessageText(message.uid);
                break;
            case 'file':
            case 'image':
            case 'video':
            case 'audio':
                text = this._getCaption(this._getTableForFileType(message.type), message.uid);
                break;
            case 'deleted':
                text = undefined;
                break;
            case 'poll':
                text = undefined;
                break;
            default:
                unreachable(message.type);
        }

        return text;
    }

    /** @inheritdoc */
    public getContactConversationUidByIdentity(
        identity: IdentityString,
    ): DbConversationUid | undefined {
        return (
            sync(
                this._db
                    .selectFrom(tConversation)
                    .innerJoin(tContact)
                    .on(tConversation.contactUid.equals(tContact.uid))
                    .selectOneColumn(tConversation.uid)
                    .where(
                        tContact.identity
                            .equals(identity)
                            .and(tConversation.contactUid.isNotNull()),
                    )
                    .executeSelectNoneOrOne(),
            ) ?? undefined
        );
    }

    /** @inheritdoc */
    public getGroupConversationUidByCreatorIdentity(
        creator: IdentityString | undefined,
        groupId: GroupId,
    ): DbConversationUid | undefined {
        // If the creator is not the user, we need to join with the contacts to check the identity.
        if (creator !== undefined) {
            return (
                sync(
                    this._db
                        .selectFrom(tConversation)
                        .innerJoin(tGroup)
                        .on(tConversation.groupUid.equals(tGroup.uid))
                        .innerJoin(tContact)
                        .on(tGroup.creatorUid.equals(tContact.uid))
                        .selectOneColumn(tConversation.uid)
                        .where(
                            tContact.identity
                                .equalsIfValue(creator)
                                .and(tGroup.groupId.equals(groupId))
                                .and(tConversation.groupUid.isNotNull()),
                        )
                        .executeSelectNoneOrOne(),
                ) ?? undefined
            );
        }

        // If the user is the creator, we can directly extract the conversation Uid in a single join
        return (
            sync(
                this._db
                    .selectFrom(tConversation)
                    .innerJoin(tGroup)
                    .on(tConversation.groupUid.equals(tGroup.uid))
                    .selectOneColumn(tConversation.uid)
                    .where(
                        tGroup.creatorUid
                            .isNull()
                            .and(tGroup.groupId.equals(groupId))
                            .and(tConversation.groupUid.isNotNull()),
                    )
                    .executeSelectNoneOrOne(),
            ) ?? undefined
        );
    }

    /** @inheritdoc */
    public storeRunningGroupCalls(
        groupUid: DbGroupUid,
        groupCalls: readonly DbCreate<DbRunningGroupCall>[],
    ): boolean {
        assert(
            groupCalls.find((call) => call.groupUid !== groupUid) === undefined,
            'The group uid must correspond to the groupUid of all calls',
        );
        return this._db.syncTransaction(() => {
            // Delete all running group call from this group
            sync(
                this._db
                    .deleteFrom(tRunningGroupCalls)
                    .where(tRunningGroupCalls.groupUid.equals(groupUid))
                    .executeDelete(),
            );
            const dbGroupCalls = groupCalls.map((call) => ({...call, groupUid}));

            // Insert currently running group calls of this group into the db.
            const inserted = sync(
                this._db.insertInto(tRunningGroupCalls).values(dbGroupCalls).executeInsert(),
            );
            return inserted > 0;
        }, this._log);
    }

    /** @inheritdoc */
    public getRunningGroupCalls(groupUid: DbGroupUid): DbList<DbRunningGroupCall> {
        const groupUserState = sync(
            this._db
                .selectFrom(tGroup)
                .selectOneColumn(tGroup.userState)
                .where(tGroup.uid.equals(groupUid))
                .executeSelectOne(),
        );

        // When the user is not a member anymore, we just delete all ongoing calls of this group (if
        // any).
        if (groupUserState !== GroupUserState.MEMBER) {
            const deleted = sync(
                this._db
                    .deleteFrom(tRunningGroupCalls)
                    .where(tRunningGroupCalls.groupUid.equals(groupUid))
                    .executeDelete(),
            );
            if (deleted > 0) {
                this._log.debug(
                    `Deleted ${deleted} ongoing group calls in group with uid ${groupUid} because the user is not a member any more`,
                );
            }
            return [];
        }
        return sync(
            this._db
                .selectFrom(tRunningGroupCalls)
                .select({
                    uid: tRunningGroupCalls.uid,
                    groupUid: tRunningGroupCalls.groupUid,
                    nFailed: tRunningGroupCalls.nFailed,
                    startedAt: tRunningGroupCalls.startedAt,
                    creatorIdentity: tRunningGroupCalls.creatorIdentity,
                    protocolVersion: tRunningGroupCalls.protocolVersion,
                    gck: tRunningGroupCalls.gck,
                    baseUrl: tRunningGroupCalls.baseUrl,
                })
                .where(tRunningGroupCalls.groupUid.equals(groupUid))
                .executeSelectMany(),
        );
    }

    /** @inheritdoc */
    public createPollMessage(message: DbCreateMessage<DbPollMessage>): DbCreated<DbPollMessage> {
        return this._db.syncTransaction(() => {
            let type: PollMessageType;
            switch (message.pollMessageType) {
                case PollMessageType.POLL_CLOSED:
                    type = PollMessageType.POLL_CLOSED;
                    break;

                case PollMessageType.POLL_CREATED:
                case undefined:
                    type = PollMessageType.POLL_CREATED;
                    break;

                default:
                    unreachable(message.pollMessageType);
            }

            let pollUid: DbPollUid | undefined;
            // If the poll message type is closed, we don't insert new poll data. The poll update
            // must have happened before in `closePoll`.
            if (type === PollMessageType.POLL_CLOSED) {
                pollUid = this.getPoll(
                    message.pollCreatorIdentity,
                    message.conversationUid,
                    message.pollId,
                )?.uid;
                assert(pollUid !== undefined, 'The poll referenced by a closed poll must exist');
            } else {
                pollUid = this._insertPollData(message);
            }

            // Common message
            const messageUid: DbMessageUid = this._insertCommonMessageData(message);

            // Poll message
            sync(
                this._db
                    .insertInto(tMessagePollData)
                    .set({
                        messageUid,
                        type,
                        pollUid,
                    })
                    .executeInsert(),
            );

            // Note: Returning the UID of the main message, not of the messagePollData
            return messageUid;
        }, this._log);
    }

    /** @inheritdoc */
    public getPollMessageFragment(
        creatorIdentity: IdentityString,
        conversationUid: DbConversationUid,
        pollId: PollId,
    ): DbPollMessageFragment | undefined {
        // TODO(DESK-1828) we should rewrite this using joins
        const poll = this.getPoll(creatorIdentity, conversationUid, pollId);
        if (poll === undefined) {
            this._log.warn(`No poll with pollId ${pollId} found.`);
            return undefined;
        }

        const choices = this._getPollChoicesByPollUid(poll.uid).map((choice) => ({
            ...choice,
            votes: this._getPollVotesByChoiceUid(choice.uid),
        }));

        return {
            ...poll,
            choices,
        };
    }

    /** @inheritdoc */
    public updatePollVotes(
        conversationUid: DbConversationUid,
        pollVotes: DbPollVoteFragment,
        senderIdentity: IdentityString,
    ): void {
        const poll = this.getPoll(pollVotes.creatorIdentity, conversationUid, pollVotes.pollId);
        if (poll === undefined) {
            return;
        }

        for (const vote of pollVotes.choices) {
            const choiceUid = sync(
                this._db
                    .selectFrom(tPollChoices)
                    .select({
                        uid: tPollChoices.uid,
                    })
                    .where(
                        tPollChoices.pollUid
                            .equals(poll.uid)
                            .and(tPollChoices.choiceId.equals(vote.choiceId)),
                    )
                    .executeSelectOne(),
            );

            sync(
                this._db
                    .insertInto(tPollVotes)
                    .set({
                        senderIdentity,
                        choiceUid: choiceUid.uid,
                        selected: vote.selected,
                    })
                    .onConflictOn(tPollVotes.senderIdentity, tPollVotes.choiceUid)
                    .doUpdateSet({
                        senderIdentity,
                        choiceUid: choiceUid.uid,
                        selected: vote.selected,
                    })
                    .executeInsert(),
            );
        }
    }

    /** @inheritdoc */
    public closePoll(pollLookup: DbPollLookup, pollUpdate: DbPollCloseUpdate): void {
        const poll = this.getPoll(
            pollLookup.pollCreatorIdentity,
            pollLookup.conversationUid,
            pollLookup.pollId,
        );
        if (poll === undefined) {
            this._log.warn(`Poll with pollId ${pollLookup.pollId} not found, abort`);
            return;
        }

        // Update poll status to closed
        const rowsUpdated = sync(
            this._db
                .update(tPolls)
                .set({pollState: PollState.CLOSED})
                .where(tPolls.uid.equals(poll.uid))
                .executeUpdate(),
        );

        if (rowsUpdated === 1) {
            if (poll.displayMode === PollDisplayMode.LIST) {
                // Overwrite all votes with the final result which is the single source of truth.
                pollUpdate.participants.forEach((senderIdentity, index) => {
                    const pollVoteFragment: DbPollVoteFragment = {
                        pollId: pollLookup.pollId,
                        choices: pollUpdate.choices.map((choice) => {
                            assert(
                                Array.isArray(choice.participantVotes) &&
                                    choice.participantVotes.length ===
                                        pollUpdate.participants.length,
                                'Number of participants and participants votes mismatch',
                            );
                            return {
                                choiceId: choice.choiceId,
                                selected: choice.participantVotes[index] === 1,
                            };
                        }),
                        creatorIdentity: pollLookup.pollCreatorIdentity,
                    };
                    this.updatePollVotes(
                        pollLookup.conversationUid,
                        pollVoteFragment,
                        senderIdentity,
                    );
                });
            } else {
                // Just set the total amount of votes for each choice
                for (const choice of pollUpdate.choices) {
                    sync(
                        this._db
                            .update(tPollChoices)
                            .set({totalAmountVotes: choice.totalAmountVotes})
                            .where(
                                tPollChoices.choiceId
                                    .equals(choice.choiceId)
                                    .and(tPollChoices.pollUid.equals(poll.uid)),
                            )
                            .executeUpdate(),
                    );
                }
            }
        }
    }

    /** @inheritdoc */
    public getPoll(
        creatorIdentity: IdentityString,
        conversationUid: DbConversationUid,
        pollId: PollId,
    ): DbGet<DbPoll> {
        return (
            sync(
                this._db
                    .selectFrom(tPolls)
                    .select({
                        uid: tPolls.uid,
                        pollId: tPolls.pollId,
                        conversationUid: tPolls.conversationUid,
                        pollCreatorIdentity: tPolls.pollCreatorIdentity,
                        createdAt: tPolls.createdAt,
                        description: tPolls.description,
                        pollState: tPolls.pollState,
                        answerType: tPolls.answerType,
                        announceType: tPolls.announceType,
                        choicesType: tPolls.choicesType,
                        displayMode: tPolls.displayMode,
                    })
                    .where(
                        tPolls.conversationUid
                            .equals(conversationUid)
                            .and(tPolls.pollId.equals(pollId))
                            .and(tPolls.pollCreatorIdentity.equals(creatorIdentity)),
                    )
                    .executeSelectNoneOrOne(),
            ) ?? undefined
        );
    }

    private _getPollChoicesByPollUid(pollUid: DbPollUid): readonly DbChoice[] {
        return sync(
            this._db
                .selectFrom(tPollChoices)
                .select({
                    uid: tPollChoices.uid,
                    pollUid: tPollChoices.pollUid,
                    choiceId: tPollChoices.choiceId,
                    description: tPollChoices.description,
                    sortKey: tPollChoices.sortKey,
                    totalAmountVotes: tPollChoices.totalAmountVotes,
                })
                .where(tPollChoices.pollUid.equals(pollUid))
                .orderBy(tPollChoices.sortKey)
                .executeSelectMany(),
        );
    }

    private _getPollVotesByChoiceUid(choiceUid: DbChoiceUid): readonly DbVote[] {
        return sync(
            this._db
                .selectFrom(tPollVotes)
                .select({
                    uid: tPollVotes.uid,
                    senderIdentity: tPollVotes.senderIdentity,
                    choiceUid: tPollVotes.choiceUid,
                    selected: tPollVotes.selected,
                })
                .where(tPollVotes.choiceUid.equals(choiceUid))
                .executeSelectMany(),
        );
    }

    /**
     * Insert poll choice data into the database.
     */
    private _insertPollChoiceData(choice: Omit<DbChoice, 'uid'>): DbChoiceUid {
        return sync(
            this._db
                .insertInto(tPollChoices)
                .set({
                    pollUid: choice.pollUid,
                    choiceId: choice.choiceId,
                    description: choice.description,
                    sortKey: choice.sortKey,
                    totalAmountVotes: choice.totalAmountVotes ?? 0,
                })
                .returningLastInsertedId()
                .executeInsert(),
        );
    }

    /**
     * Insert poll data into the database.
     */
    private _insertPollData(message: DbCreateMessage<DbPollMessage>): DbPollUid {
        // Insert Poll
        const pollUid = sync(
            this._db
                .insertInto(tPolls)
                .set({
                    pollId: message.pollId,
                    pollCreatorIdentity: message.pollCreatorIdentity,
                    createdAt: new Date(),
                    conversationUid: message.conversationUid,
                    description: message.description,
                    pollState: message.pollState,
                    answerType: message.answerType,
                    announceType: message.announceType,
                    choicesType: message.choicesType,
                    displayMode: message.displayMode,
                })
                .returningLastInsertedId()
                .executeInsert(),
        );

        // Insert poll choices
        message.choices.forEach((choice) => this._insertPollChoiceData({...choice, pollUid}));

        return pollUid;
    }

    /* eslint-enable @typescript-eslint/member-ordering */
}

